"use strict";(globalThis.webpackChunkgrc||=[]).push([[23776],{61379(e){e.exports=JSON.parse('[{"citeKey":"xu2026vigil","slug":"xu-2026-trigger-render-reason-multimodal-llm-agents-c360","title":"Trigger, Render, Reason: Multimodal LLM Agents for Science-Aware Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Gainaru","S. Klasky","A. Kougkas","X.-H. Sun"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Conference","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific simulations on leadership-class HPC systems routinely waste millions of core-hours producing invalid results, yet no tool monitors whether a running simulation computes valid science. We call this blind spot dark waste: simulations that run to completion while computing the wrong answer. We present Vigil, which couples deterministic science-aware triggers with multimodal LLM confirmation through a trigger-render-reason pipeline. Vigil instruments simulations with lightweight checks on derived-quantity operators and regions of interest; when a check detects a potential anomaly, the flagged data is rendered and analyzed by a multimodal model to assess scientific validity. Upon confirming invalid behavior, Vigil can terminate or restart the simulation from a checkpoint, preventing further expenditure on dark waste. We evaluate Vigil across four codes spanning numerical instability, pattern dynamics, turbulence dissipation, and molecular-dynamics failures. Vigil detects every deliberately configured failure with zero false positives and supplies an actionable semantic verdict for each alert.","hasAbstract":true,"lede":"We present Vigil, which couples deterministic science-aware triggers with multimodal LLM confirmation through a trigger-render-reason pipeline.","links":{"program":"https://sc26.conference-program.com/presentation/?id=pap1039&sess=sess236"},"tags":["Coeus","IOWarp"],"_projectIds":["iowarp","coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026triggergated","slug":"xu-2026-trigger-gated-multimodal-1a84","title":"Trigger-Gated Multimodal LLM Agents for In-situ Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Kougkas","A. Gainaru","S. Klasky","X.-H. Sun","J. Lofstead"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"WIP","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdswwip113&sess=sess129"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026derivedquantity","slug":"xu-2026-rich-io-centric-derived-quantity-8c30","title":"Rich I/O-centric Derived Quantity Operators for Advanced In Situ Processing","authors":["H. Xu","J. Cernuda","A. Kougkas","X.-H. Sun","A. Gainaru","S. Klasky","M. Taufer","N. Tan","K. Assogba","M. Rafique","B. Nicolae","J. Teves","C. Brinker","L. Pouchard","J. Lofstead"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations. Although performing analysis directly as data is produced (in situ) can mitigate this problem, embedding such analysis routines into complex scientific codes is often impractical or inflexible. We address this by introducing derived quantity operators that provide a modular and pluggable framework within high-level I/O libraries, enabling sophisticated in situ analysis to be performed transparently during data output with minimal modifications to the host application. The operators bind to persistent hierarchical storage through operator-declared metadata, allowing cross-timestep and cross-run analysis to be carried out seamlessly within the I/O path. We demonstrate the capabilities of our operators by integrating correctness validation and important scientific metrics, traditionally executed after simulation runs, directly into the I/O pathway as derived quantities. Our implementation illustrates how complex, non-mathematical analyses such as runtime validation can be efficiently performed during simulation, enabling early detection of errors. Our work broadens the range of in situ analyses achievable through derived quantity operators, promoting more flexible, intelligent, and reliable scientific workflows.","hasAbstract":true,"lede":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations.","links":{"pdf":"https://grc.iit.edu/papers/2026/xu-2026-rich-io-centric-derived-quantity-8c30.pdf"},"tags":["IOWarp","Coeus"],"_projectIds":["iowarp","coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"xu2026vigilposter","slug":"xu-2026-trigger-render-reason-poster-4c63","title":"Trigger, Render, Reason: Multimodal LLM Agents for Science-Aware Scientific Simulation Monitoring","authors":["H. Xu"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"program":"https://gcasr.org/2026/posters"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"xu2025richoperators","slug":"xu-2025-rich-operators-a3f2","title":"Rich Operators for Advanced In Situ Processing","authors":["H. Xu","A. Kougkas","X.-H. Sun"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/3780_Hua.pdf"},"tags":["HPC","Metadata Management","Storage"],"_projectIds":["coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"}]')}}]);